def countDecodingsWild(symbols):
    M = 1000000007

    def one(x):
        if x == -1:
            return 9
        return 0 if x == 0 else 1

    def two(a, b):
        if a == -1 and b == -1:
            return 15
        if a == -1:
            return 2 if b <= 6 else 1
        if b == -1:
            if a == 1:
                return 9
            if a == 2:
                return 6
            return 0
        return 1 if 10 <= a * 10 + b <= 26 else 0

    p2, p1 = 0, 1       # dp[i-2], dp[i-1]; dp[0] = 1
    for i, x in enumerate(symbols):
        cur = p1 * one(x)
        if i >= 1:
            cur += p2 * two(symbols[i - 1], x)
        p2, p1 = p1, cur % M
    return p1
